draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 80);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 40);
  ctx.lineTo(W/2 - 30 + 20*Math.sin(t), H/2 + 60);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 40);
  ctx.lineTo(W/2 + 30 - 20*Math.sin(t), H/2 + 60);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 80);
  ctx.lineTo(W/2 - 20 + 10*Math.sin(t), H/2 + 110);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 80);
  ctx.lineTo(W/2 + 20 - 10*Math.sin(t), H/2 + 110);
  ctx.stroke();

  // paper
  ctx.fillStyle = 'white';
  ctx.fillRect(W/2 - 50, H/2 - 50, 100, 100);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.strokeRect(W/2 - 50, H/2 - 50, 100, 100);

  // sharing
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 80);
  ctx.lineTo(W/2 - 20 + 10*Math.sin(t), H/2 - 20);
  ctx.stroke();

  ctx.restore();
}
